function pad({ bodies, selection, settings }) {
  const face = bodies.find(b => b.id === selection[0].body).faces.find(f => f.id === selection[0].face);
  const { u, v } = face.plane;
  const n = face.offsetHandle?.normal ?? [u[1]*v[2]-u[2]*v[1], u[2]*v[0]-u[0]*v[2], u[0]*v[1]-u[1]*v[0]];
  const center = face.signature.slice(3, 6);
  const h = settings.width / 2;
  const vertices = [[-h,-h,-0.01],[h,-h,-0.01],[h,h,-0.01],[-h,h,-0.01],[-h,-h,settings.height],[h,-h,settings.height],[h,h,settings.height],[-h,h,settings.height]]
    .map(([x,y,z]) => center.map((c,i) => c + x*u[i] + y*v[i] + z*n[i]));
  const triangles = [[0,2,1],[0,3,2],[4,5,6],[4,6,7],[0,1,5],[0,5,4],[1,2,6],[1,6,5],[2,3,7],[2,7,6],[3,0,4],[3,4,7]];
  const cross = [u[1]*v[2]-u[2]*v[1], u[2]*v[0]-u[0]*v[2], u[0]*v[1]-u[1]*v[0]];
  if (n.reduce((sum, value, i) => sum + value*cross[i], 0) < 0) triangles.forEach(t => t.reverse());
  return { vertices, triangles };
}
export default {
  partition(context) {
    const groups = new Map();
    for (const ref of context.selection) {
      const face = context.bodies.find(b => b.id === ref.body).faces.find(f => f.id === ref.face);
      if (!face.plane) return { reason: "Linked pads require planar faces" };
      const group = groups.get(ref.body) ?? { faces: [] };
      group.faces.push(ref);
      groups.set(ref.body, group);
    }
    return { groups: [...groups.values()] };
  },
  validate(context) {
    return context.selection.every(ref => context.bodies.find(b => b.id === ref.body).faces.find(f => f.id === ref.face).plane)
      ? [] : [{ severity: "error", message: "Linked pads require planar faces", faces: context.selection }];
  },
  preview(context) {
    const result = { vertices: [], triangles: [] };
    for (const face of context.selection) {
      const mesh = pad({ ...context, selection: [face] });
      const offset = result.vertices.length;
      result.vertices.push(...mesh.vertices);
      result.triangles.push(...mesh.triangles.map(t => t.map(i => i + offset)));
    }
    return result;
  },
  generate(context) {
    return context.selection.map(face => ({ operation: "add", mesh: pad({ ...context, selection: [face] }) }));
  }
};
